INSERT INTO _seed_expected VALUES
(1,'seed_seunghak_v1_01',35.1169200,128.9687200,'기쁨','#765A08','드디어 이해한 한 페이지','동아대학교 한림도서관','한림도서관에서 몇 번이나 다시 읽던 전공 내용이 드디어 이해됐다. 노트에 내 말로 정리하고 나니 하루 종일 공부한 보람이 느껴진다.',ARRAY['LIBRARY','INDOOR','QUIET']::text[]),
(2,'seed_seunghak_v1_02',35.1169200,128.9687200,'기대','#4F711F','새 책과 시작하는 오후','동아대학교 한림도서관','한림도서관에서 읽고 싶던 책을 빌렸다. 창가에 앉아 첫 장을 펼치니 이번 주 공강 시간이 기다려진다.',ARRAY['LIBRARY','INDOOR','CALM']::text[]),
(3,'seed_seunghak_v1_03',35.1169200,128.9687200,'슬픔','#315C86','함께 공부하던 빈자리','동아대학교 한림도서관','늘 같이 공부하던 친구가 휴학해서 오늘은 한림도서관에 혼자 왔다. 맞은편 빈 의자를 보니 별말 없이 함께하던 시간이 그립다.',ARRAY['LIBRARY','INDOOR','QUIET']::text[]),
(4,'seed_seunghak_v1_04',35.1169200,128.9687200,'분노','#9D312B','사라진 공동 과제 파일','동아대학교 한림도서관','한림도서관에서 팀 과제를 열었는데 상의도 없이 내 작업 부분이 삭제되어 있었다. 밤새 정리한 자료라 화가 나서 잠깐 자리에서 일어났다.',ARRAY['LIBRARY','INDOOR']::text[]),
(5,'seed_seunghak_v1_05',35.1169200,128.9687200,'불안','#5C477D','시험 범위가 너무 넓다','동아대학교 한림도서관','한림도서관 책상에 시험 자료를 펼쳤는데 아직 못 본 부분이 너무 많다. 시간을 확인할수록 마음만 급해져서 우선 한 단원부터 끝내기로 했다.',ARRAY['LIBRARY','INDOOR','QUIET']::text[]),
(6,'seed_seunghak_v1_06',35.1169200,128.9687200,'당황','#8B3D66','울려 버린 알람','동아대학교 한림도서관','한림도서관에서 휴대폰을 무음으로 바꿨다고 생각했는데 알람이 크게 울렸다. 급하게 끄면서 주변에 고개를 숙였더니 얼굴이 뜨거워졌다.',ARRAY['LIBRARY','INDOOR','QUIET']::text[]),
(7,'seed_seunghak_v1_07',35.1169200,128.9687200,'놀람','#28746F','책 사이에서 만난 관심사','동아대학교 한림도서관','한림도서관 서가를 둘러보다 내 과제 주제와 딱 맞는 책을 발견했다. 다른 분야 코너에서 찾을 줄은 몰라서 혼자 작게 감탄했다.',ARRAY['LIBRARY','INDOOR']::text[]),
(8,'seed_seunghak_v1_08',35.1169200,128.9687200,'짜증','#925021','같은 문장을 세 번째','동아대학교 한림도서관','한림도서관에 앉아 있는데 자꾸 휴대폰을 확인하느라 같은 문장을 반복해서 읽었다. 집중하지 못하는 내 모습에 짜증이 나서 폰을 가방에 넣었다.',ARRAY['LIBRARY','INDOOR']::text[]),
(9,'seed_seunghak_v1_09',35.1169200,128.9687200,'기쁨','#765A08','계획표의 마지막 체크','동아대학교 한림도서관','한림도서관에서 오늘 할 공부를 모두 끝냈다. 계획표 마지막 칸에 체크하고 가방을 챙기는 순간 마음이 가벼워졌다.',ARRAY['LIBRARY','INDOOR','CALM']::text[]),
(10,'seed_seunghak_v1_10',35.1169200,128.9687200,'기대','#4F711F','내일은 조금 더 수월하게','동아대학교 한림도서관','한림도서관에서 다음 수업 자료를 미리 읽었다. 낯설던 용어들이 눈에 익어서 내일 강의를 조금 편하게 들을 수 있을 것 같다.',ARRAY['LIBRARY','INDOOR','QUIET']::text[]),
(11,'seed_seunghak_v1_02',35.1152500,128.9681800,'슬픔','#315C86','혼자 먹는 늦은 점심','동아대학교 승학캠퍼스 학생회관','학생회관에서 수업 시간을 놓쳐 늦은 점심을 혼자 먹었다. 친구들 단체 사진을 보다 보니 함께 밥 먹던 평범한 날이 유난히 생각났다.',ARRAY['INDOOR','REST']::text[]),
(12,'seed_seunghak_v1_03',35.1152500,128.9681800,'분노','#9D312B','빠진 이름 한 줄','동아대학교 승학캠퍼스 학생회관','학생회관에서 동아리 자료를 확인하다 내가 준비한 행사에 내 이름만 빠진 걸 봤다. 역할을 나눌 때부터 함께했는데 인정받지 못한 기분이라 속상하고 화가 났다.',ARRAY['INDOOR','SOCIAL']::text[]),
(13,'seed_seunghak_v1_04',35.1152500,128.9681800,'불안','#5C477D','처음 들어가는 모임','동아대학교 승학캠퍼스 학생회관','학생회관에서 처음 참여하는 동아리 모임을 기다렸다. 안에서 웃음소리가 들리는데 나만 어색하게 서 있을까 봐 문 앞에서 몇 번이나 심호흡했다.',ARRAY['INDOOR','SOCIAL']::text[]),
(14,'seed_seunghak_v1_05',35.1152500,128.9681800,'당황','#8B3D66','다른 테이블에 놓은 가방','동아대학교 승학캠퍼스 학생회관','학생회관에서 친구인 줄 알고 옆 테이블에 가방을 놓았는데 처음 보는 사람이었다. 바로 사과하고 돌아왔지만 친구들이 웃어서 더 민망했다.',ARRAY['INDOOR','FRIENDS']::text[]),
(15,'seed_seunghak_v1_06',35.1152500,128.9681800,'놀람','#28746F','뜻밖의 생일 축하','동아대학교 승학캠퍼스 학생회관','학생회관에서 밥만 먹기로 했는데 친구들이 작은 케이크를 꺼냈다. 바쁜 주라 다들 잊은 줄 알았는데 내 생일을 기억해 줘서 놀랐다.',ARRAY['INDOOR','FRIENDS','SOCIAL']::text[]),
(16,'seed_seunghak_v1_07',35.1152500,128.9681800,'짜증','#925021','결정만 하다 끝난 공강','동아대학교 승학캠퍼스 학생회관','학생회관에 모여 점심 메뉴를 고르다가 공강 시간이 거의 지나갔다. 아무도 결정을 안 해서 배고픈데 시간까지 아까워 괜히 예민해졌다.',ARRAY['INDOOR','FRIENDS','BUSY']::text[]),
(17,'seed_seunghak_v1_08',35.1152500,128.9681800,'기쁨','#765A08','밥 한 끼의 위로','동아대학교 승학캠퍼스 학생회관','학생회관에서 친구에게 요즘 힘든 일을 털어놨다. 별다른 해결책 없이도 끝까지 들어주는 사람이 있으니 밥 먹고 나오는 발걸음이 훨씬 가벼웠다.',ARRAY['INDOOR','FRIENDS','CONVERSATION','COMFORT']::text[]),
(18,'seed_seunghak_v1_09',35.1152500,128.9681800,'기대','#4F711F','새 동아리의 첫 약속','동아대학교 승학캠퍼스 학생회관','학생회관에서 동아리 사람들과 첫 활동 계획을 정했다. 서로 해 보고 싶은 이야기를 꺼내다 보니 다음 만남이 벌써 기다려진다.',ARRAY['INDOOR','SOCIAL','CONVERSATION']::text[]),
(19,'seed_seunghak_v1_10',35.1152500,128.9681800,'슬픔','#315C86','마지막으로 맞춘 점심시간','동아대학교 승학캠퍼스 학생회관','학생회관에서 졸업을 앞둔 선배와 점심을 먹었다. 다음 학기에는 이렇게 쉽게 만나지 못한다는 생각에 식사가 끝나도 한참 자리를 못 떴다.',ARRAY['INDOOR','CONVERSATION']::text[]),
(20,'seed_seunghak_v1_01',35.1152500,128.9681800,'분노','#9D312B','약속을 가볍게 넘긴 말','동아대학교 승학캠퍼스 학생회관','학생회관에서 기다린 지 한참 뒤에야 모임이 취소됐다는 연락을 받았다. 미리 말해 줄 수 있었을 텐데 내 시간은 중요하지 않은 것 같아 화가 났다.',ARRAY['INDOOR','SOCIAL']::text[]),
(21,'seed_seunghak_v1_03',35.1160900,128.9676200,'불안','#5C477D','발표 직전의 복도','동아대학교 공과대학 1호관','공과대학 1호관 복도에서 발표 자료를 다시 넘겼다. 연습할 때는 괜찮았는데 강의실 문이 열릴 때마다 준비한 말을 잊을까 봐 긴장된다.',ARRAY['INDOOR','BUSY']::text[]),
(22,'seed_seunghak_v1_04',35.1160900,128.9676200,'당황','#8B3D66','연결되지 않는 화면','동아대학교 공과대학 1호관','공과대학 1호관에서 발표를 시작하려는데 노트북 화면이 나오지 않았다. 모두 기다리는 동안 케이블을 다시 꽂느라 손이 바빠졌다.',ARRAY['INDOOR']::text[]),
(23,'seed_seunghak_v1_05',35.1160900,128.9676200,'놀람','#28746F','한 번에 성공한 실험','동아대학교 공과대학 1호관','공과대학 1호관에서 계속 실패하던 실험이 설정 하나를 바꾸자 제대로 작동했다. 팀원들과 결과를 다시 확인하며 믿기지 않아 서로 쳐다봤다.',ARRAY['INDOOR','ACTIVE']::text[]),
(24,'seed_seunghak_v1_06',35.1160900,128.9676200,'짜증','#925021','저장 직전에 멈춘 작업','동아대학교 공과대학 1호관','공과대학 1호관에서 과제 마무리 중 프로그램이 멈췄다. 마지막으로 저장한 시간이 한참 전이라 다시 해야 할 부분을 보고 한숨이 나왔다.',ARRAY['INDOOR','BUSY']::text[]),
(25,'seed_seunghak_v1_07',35.1160900,128.9676200,'기쁨','#765A08','팀으로 끝낸 설계','동아대학교 공과대학 1호관','공과대학 1호관에서 팀 설계 과제를 제출했다. 의견이 갈릴 때도 많았지만 마지막에는 서로 도와서 완성해 내니 혼자 잘했을 때보다 뿌듯하다.',ARRAY['INDOOR','FRIENDS','ACTIVE']::text[]),
(26,'seed_seunghak_v1_08',35.1160900,128.9676200,'기대','#4F711F','아이디어가 모이는 시간','동아대학교 공과대학 1호관','공과대학 1호관에서 새 프로젝트 주제를 정했다. 말로만 상상하던 기능을 실제로 만들 생각에 공책 가득 아이디어를 적었다.',ARRAY['INDOOR','CONVERSATION','ACTIVE']::text[]),
(27,'seed_seunghak_v1_09',35.1160900,128.9676200,'슬픔','#315C86','노력과 다른 결과','동아대학교 공과대학 1호관','공과대학 1호관 수업을 마치고 평가 결과를 확인했다. 준비한 시간에 비해 점수가 낮아서 복도에 잠깐 앉아 마음을 추슬렀다.',ARRAY['INDOOR']::text[]),
(28,'seed_seunghak_v1_10',35.1160900,128.9676200,'분노','#9D312B','또 혼자 남은 마무리','동아대학교 공과대학 1호관','공과대학 1호관에서 팀 과제를 마무리하는데 약속한 자료가 끝내 오지 않았다. 반복해서 내 몫이 늘어나니 더는 괜찮다고 넘기기 어려웠다.',ARRAY['INDOOR','BUSY']::text[]),
(29,'seed_seunghak_v1_01',35.1160900,128.9676200,'불안','#5C477D','풀리지 않는 마지막 문제','동아대학교 공과대학 1호관','공과대학 1호관 앞에서 시험을 기다리며 마지막 문제를 다시 봤다. 익숙한 유형인데 풀이가 떠오르지 않아 자신감이 흔들렸다.',ARRAY['OUTDOOR']::text[]),
(30,'seed_seunghak_v1_02',35.1160900,128.9676200,'당황','#8B3D66','질문의 뜻을 다시 듣다','동아대학교 공과대학 1호관','공과대학 1호관 수업에서 자신 있게 답했는데 교수님 질문을 반대로 이해한 거였다. 다시 설명을 듣고 답했지만 순간 머릿속이 하얘졌다.',ARRAY['INDOOR']::text[]),
(31,'seed_seunghak_v1_04',35.1149000,128.9675800,'놀람','#28746F','다르게 읽힌 문장','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 수업에서 친구의 해석을 들었는데 같은 글이 전혀 다르게 보였다. 당연하다고 생각한 의미가 하나 더 생겨서 수업 뒤에도 계속 떠올랐다.',ARRAY['INDOOR','CONVERSATION']::text[]),
(32,'seed_seunghak_v1_05',35.1149000,128.9675800,'짜증','#925021','출력물이 없는 아침','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 앞에 도착해서야 제출할 출력물을 방에 두고 온 걸 알았다. 아침에 몇 번이나 챙겼다고 생각했는데 허탈하고 짜증이 났다.',ARRAY['OUTDOOR','BUSY']::text[]),
(33,'seed_seunghak_v1_06',35.1149000,128.9675800,'기쁨','#765A08','내 의견을 끝까지 말하다','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 토론 수업에서 처음으로 내 생각을 끝까지 이야기했다. 다른 학생이 공감해 줘서 수업을 마친 뒤에도 기분 좋은 여운이 남았다.',ARRAY['INDOOR','CONVERSATION','SOCIAL']::text[]),
(34,'seed_seunghak_v1_07',35.1149000,128.9675800,'기대','#4F711F','새로운 강의의 첫날','동아대학교 승학캠퍼스 인문과학대학','인문과학대학에서 듣고 싶었던 교양 수업의 첫 강의를 들었다. 강의 계획서에 관심 있던 주제가 많아서 이번 학기가 조금 더 기대된다.',ARRAY['INDOOR']::text[]),
(35,'seed_seunghak_v1_08',35.1149000,128.9675800,'슬픔','#315C86','돌려받은 짧은 글','동아대학교 승학캠퍼스 인문과학대학','인문과학대학에서 돌려받은 글에 내 의도가 잘 전달되지 않았다는 평이 있었다. 나름 진심을 담았던 글이라 종이를 접어 넣으며 마음이 무거웠다.',ARRAY['INDOOR']::text[]),
(36,'seed_seunghak_v1_09',35.1149000,128.9675800,'분노','#9D312B','말을 끊긴 토론','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 토론에서 내 설명이 끝나기도 전에 비웃는 말을 들었다. 의견이 다른 건 괜찮지만 말할 기회마저 빼앗긴 것 같아 화가 났다.',ARRAY['INDOOR','CONVERSATION']::text[]),
(37,'seed_seunghak_v1_10',35.1149000,128.9675800,'불안','#5C477D','아직 비어 있는 첫 문장','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 수업을 앞두고 글쓰기 과제를 다시 열었다. 생각은 많은데 첫 문장이 나오지 않아서 마감 시간이 가까워질수록 초조해졌다.',ARRAY['INDOOR']::text[]),
(38,'seed_seunghak_v1_01',35.1149000,128.9675800,'당황','#8B3D66','층을 잘못 올라왔다','동아대학교 승학캠퍼스 인문과학대학','인문과학대학에서 익숙한 문을 열었는데 다른 수업이 진행 중이었다. 강의실 호수를 다시 확인하고 조용히 나오는 길이 유난히 길게 느껴졌다.',ARRAY['INDOOR']::text[]),
(39,'seed_seunghak_v1_02',35.1149000,128.9675800,'놀람','#28746F','뜻밖에 이어진 질문','동아대학교 승학캠퍼스 인문과학대학','인문과학대학 수업이 끝나고 가볍게 던진 질문이 친구들과 긴 대화로 이어졌다. 같은 주제에 이렇게 다양한 경험이 있는 줄 몰랐다.',ARRAY['INDOOR','FRIENDS','CONVERSATION']::text[]),
(40,'seed_seunghak_v1_03',35.1149000,128.9675800,'짜증','#925021','수업 사이의 촉박한 이동','동아대학교 승학캠퍼스 인문과학대학','인문과학대학에 도착하자마자 다음 강의실까지 이동할 시간을 계산했다. 쉬지도 못하고 계단을 오르내리니 작은 일에도 예민해졌다.',ARRAY['INDOOR','BUSY']::text[]),
(41,'seed_seunghak_v1_05',35.1184200,128.9694600,'기쁨','#765A08','하루 끝의 따뜻한 인사','동아대학교 한림생활관 승학관 주변','한림생활관으로 돌아오는 길에 룸메이트와 마주쳤다. 서로 오늘 어땠는지 이야기하며 걸으니 지쳤던 하루가 다정하게 마무리됐다.',ARRAY['OUTDOOR','FRIENDS','CONVERSATION','COMFORT']::text[]),
(42,'seed_seunghak_v1_06',35.1184200,128.9694600,'기대','#4F711F','주말 계획을 세우며','동아대학교 한림생활관 승학관 주변','한림생활관 앞에서 친구와 주말 산책 약속을 잡았다. 과제만 하던 일주일 끝에 같이 바깥바람을 쐴 생각을 하니 벌써 들뜬다.',ARRAY['OUTDOOR','FRIENDS','WALK']::text[]),
(43,'seed_seunghak_v1_07',35.1184200,128.9694600,'슬픔','#315C86','집에 전화하고 돌아서는 길','동아대학교 한림생활관 승학관 주변','한림생활관 앞에서 가족과 통화를 마쳤다. 잘 지낸다고 말했지만 익숙한 목소리를 듣고 나니 오늘따라 집밥과 내 방이 그립다.',ARRAY['OUTDOOR','SECLUDED']::text[]),
(44,'seed_seunghak_v1_08',35.1184200,128.9694600,'분노','#9D312B','배려를 부탁한 저녁','동아대학교 한림생활관 승학관 주변','한림생활관에 돌아와 내일 일찍 일어난다고 말했는데 약속이 계속 지켜지지 않았다. 작은 부탁을 여러 번 해야 하는 상황에 마음이 거칠어졌다.',ARRAY['INDOOR']::text[]),
(45,'seed_seunghak_v1_09',35.1184200,128.9694600,'불안','#5C477D','첫 기숙사 생활','동아대학교 한림생활관 승학관 주변','한림생활관 앞에 짐을 내려놓고 새 생활을 시작하려니 긴장됐다. 낯선 사람들과 잘 지낼 수 있을지 걱정되지만 일단 먼저 인사해 보려 한다.',ARRAY['OUTDOOR']::text[]),
(46,'seed_seunghak_v1_10',35.1184200,128.9694600,'당황','#8B3D66','방에 두고 온 물건','동아대학교 한림생활관 승학관 주변','한림생활관에서 한참 내려온 뒤에야 과제에 필요한 물건을 놓고 온 걸 알았다. 약속 시간은 다가오는데 다시 올라가야 해서 친구에게 급히 연락했다.',ARRAY['OUTDOOR','BUSY']::text[]),
(47,'seed_seunghak_v1_01',35.1184200,128.9694600,'놀람','#28746F','익숙한 얼굴과의 재회','동아대학교 한림생활관 승학관 주변','한림생활관 앞에서 고등학교 때 같은 반이었던 친구를 만났다. 서로 여기 사는 줄 몰라 한동안 놀라다가 다음에 밥 먹자고 약속했다.',ARRAY['OUTDOOR','FRIENDS','SOCIAL']::text[]),
(48,'seed_seunghak_v1_02',35.1184200,128.9694600,'짜증','#925021','다시 올라가는 언덕','동아대학교 한림생활관 승학관 주변','한림생활관으로 돌아가는 길에 비까지 내려 가방과 신발이 젖었다. 우산을 챙기지 않은 게 후회돼서 마지막 언덕이 평소보다 길게 느껴졌다.',ARRAY['OUTDOOR','WALK']::text[]),
(49,'seed_seunghak_v1_03',35.1184200,128.9694600,'기쁨','#765A08','서로 나눈 작은 간식','동아대학교 한림생활관 승학관 주변','한림생활관에서 친구와 간식을 나눠 먹으며 각자 힘들었던 일을 이야기했다. 특별한 일은 없었지만 혼자가 아니라는 생각에 마음이 놓였다.',ARRAY['INDOOR','FRIENDS','COMFORT']::text[]),
(50,'seed_seunghak_v1_04',35.1184200,128.9694600,'기대','#4F711F','내일을 준비하는 밤','동아대학교 한림생활관 승학관 주변','한림생활관 앞에서 잠깐 바람을 쐬고 들어왔다. 내일 필요한 짐을 미리 챙겨 두니 새로운 하루를 조금 단정하게 시작할 수 있을 것 같다.',ARRAY['OUTDOOR','CALM','REST']::text[]),
(51,'seed_seunghak_v1_06',35.1138700,128.9664700,'슬픔','#315C86','인사가 길어진 정문','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문에서 친구를 배웅했다. 각자 바빠져 자주 못 볼 것 같다는 말을 듣고 헤어진 뒤에도 한동안 같은 자리에 서 있었다.',ARRAY['OUTDOOR','CONVERSATION']::text[]),
(52,'seed_seunghak_v1_07',35.1138700,128.9664700,'분노','#9D312B','횡단보도 앞의 순간','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문 근처에서 길을 건너려는데 차가 보행자를 보고도 속도를 줄이지 않았다. 놀란 마음이 가라앉자 안전을 가볍게 여기는 태도에 화가 났다.',ARRAY['OUTDOOR','BUSY']::text[]),
(53,'seed_seunghak_v1_08',35.1138700,128.9664700,'불안','#5C477D','첫 등교의 언덕','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문을 지나 올라가며 시간표를 몇 번이나 확인했다. 강의실을 못 찾을까 봐 일찍 왔는데도 첫 수업 생각에 발걸음이 빨라졌다.',ARRAY['OUTDOOR','WALK']::text[]),
(54,'seed_seunghak_v1_09',35.1138700,128.9664700,'당황','#8B3D66','반대 방향으로 안내했다','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문에서 길을 묻는 분께 자신 있게 설명했는데 지도를 보니 반대 방향이었다. 바로 따라가 정정하고 나니 괜히 아는 척한 것 같아 민망했다.',ARRAY['OUTDOOR','CONVERSATION']::text[]),
(55,'seed_seunghak_v1_10',35.1138700,128.9664700,'놀람','#28746F','정문에서 마주친 선배','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문에서 오래 연락하지 못했던 선배를 만났다. 멀리서 내 이름을 부르는 소리에 돌아봤는데 정말 그 선배여서 깜짝 놀랐다.',ARRAY['OUTDOOR','SOCIAL']::text[]),
(56,'seed_seunghak_v1_01',35.1138700,128.9664700,'짜증','#925021','우산이 뒤집힌 등굣길','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문을 지나는데 바람에 우산이 뒤집혔다. 수업 전부터 옷이 젖고 손까지 바빠져서 아침 기분이 엉켜 버렸다.',ARRAY['OUTDOOR','WALK']::text[]),
(57,'seed_seunghak_v1_02',35.1138700,128.9664700,'기쁨','#765A08','등교길에 들은 좋은 소식','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문 앞에서 기다리던 합격 연락을 받았다. 혼자 걷다가 저절로 웃음이 나서 가장 먼저 가족에게 전화를 걸었다.',ARRAY['OUTDOOR','WALK']::text[]),
(58,'seed_seunghak_v1_03',35.1138700,128.9664700,'기대','#4F711F','새 학기를 시작하는 발걸음','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문에서 친구와 만나 함께 올라갔다. 이번 학기에는 어떤 수업과 사람을 만날지 이야기하다 보니 언덕도 금방 지나갔다.',ARRAY['OUTDOOR','FRIENDS','WALK']::text[]),
(59,'seed_seunghak_v1_04',35.1138700,128.9664700,'슬픔','#315C86','떠나는 계절의 정문','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문을 나서며 처음 입학하던 날을 떠올렸다. 익숙해진 풍경을 매일 보지 못할 날이 다가온다는 생각에 괜히 마음이 먹먹했다.',ARRAY['OUTDOOR','WALK']::text[]),
(60,'seed_seunghak_v1_05',35.1138700,128.9664700,'분노','#9D312B','계속 미뤄지는 만남','동아대학교 승학캠퍼스 정문','승학캠퍼스 정문에서 만나기로 한 사람이 연락 없이 늦었다. 약속을 정한 쪽은 상대였는데 기다리는 내 입장을 생각하지 않는 것 같아 화가 났다.',ARRAY['OUTDOOR','BUSY']::text[]),
(61,'seed_seunghak_v1_07',35.1125400,128.9647200,'불안','#5C477D','버스가 오기 전의 초조함','동아대입구 버스정류소 주변','동아대입구 정류소에서 버스를 기다리며 도착 정보를 계속 확인했다. 중요한 약속에 늦을까 봐 멀리서 오는 버스 번호마다 눈이 갔다.',ARRAY['OUTDOOR','BUSY']::text[]),
(62,'seed_seunghak_v1_08',35.1125400,128.9647200,'당황','#8B3D66','잘못 누른 하차 벨','동아대입구 버스정류소 주변','동아대입구 정류소를 지나기 전에 습관적으로 벨을 눌렀다. 아직 내릴 곳이 아닌 걸 깨닫고 가방을 다시 내려놓는데 괜히 시선이 신경 쓰였다.',ARRAY['INDOOR','BUSY']::text[]),
(63,'seed_seunghak_v1_09',35.1125400,128.9647200,'놀람','#28746F','정류소에서 돌려받은 카드','동아대입구 버스정류소 주변','동아대입구 정류소에서 누군가 달려와 떨어뜨린 교통카드를 건네줬다. 잃어버린 줄도 몰랐는데 먼저 챙겨 준 마음에 놀라고 고마웠다.',ARRAY['OUTDOOR','SOCIAL']::text[]),
(64,'seed_seunghak_v1_10',35.1125400,128.9647200,'짜증','#925021','눈앞에서 떠난 버스','동아대입구 버스정류소 주변','동아대입구 정류소까지 서둘러 왔는데 버스가 바로 앞에서 출발했다. 조금만 일찍 나올 걸 싶어서 빈 정류소에서 한숨을 쉬었다.',ARRAY['OUTDOOR','BUSY']::text[]),
(65,'seed_seunghak_v1_01',35.1125400,128.9647200,'기쁨','#765A08','기다림이 짧아진 대화','동아대입구 버스정류소 주변','동아대입구 정류소에서 같은 수업 친구를 만났다. 과제 이야기를 나누다 보니 버스가 금방 와서 기다리는 시간까지 즐거웠다.',ARRAY['OUTDOOR','FRIENDS','CONVERSATION']::text[]),
(66,'seed_seunghak_v1_02',35.1125400,128.9647200,'기대','#4F711F','약속 장소로 가는 길','동아대입구 버스정류소 주변','동아대입구 정류소에서 오랜만에 친구들을 만나러 가는 버스를 기다렸다. 무슨 이야기를 먼저 할지 생각하니 버스가 빨리 왔으면 좋겠다.',ARRAY['OUTDOOR','SOCIAL']::text[]),
(67,'seed_seunghak_v1_03',35.1125400,128.9647200,'슬픔','#315C86','빈 옆자리가 생각났다','동아대입구 버스정류소 주변','동아대입구 정류소에서 예전에 늘 같이 버스를 타던 친구가 떠올랐다. 오늘은 혼자 이어폰을 끼고 서 있으니 같은 길도 조금 조용하게 느껴진다.',ARRAY['OUTDOOR']::text[]),
(68,'seed_seunghak_v1_04',35.1125400,128.9647200,'분노','#9D312B','줄을 무시한 탑승','동아대입구 버스정류소 주변','동아대입구 정류소에서 차례대로 기다리고 있는데 뒤에서 온 사람이 앞을 가로질러 탔다. 다들 기다린 시간을 무시하는 모습에 기분이 상했다.',ARRAY['OUTDOOR','CROWDED','BUSY']::text[]),
(69,'seed_seunghak_v1_05',35.1125400,128.9647200,'불안','#5C477D','막차 시간을 확인하며','동아대입구 버스정류소 주변','동아대입구 정류소에서 휴대폰 배터리가 얼마 남지 않은 걸 봤다. 버스 시간을 확인하고 집에 도착할 때까지 꺼지지 않기만 바랐다.',ARRAY['OUTDOOR']::text[]),
(70,'seed_seunghak_v1_06',35.1125400,128.9647200,'당황','#8B3D66','반대편에서 기다렸다','동아대입구 버스정류소 주변','동아대입구 정류소에서 한참 기다리다가 버스 방향이 반대라는 걸 알았다. 익숙한 번호만 보고 섰다가 약속 시간에 늦을까 봐 급히 길을 건넜다.',ARRAY['OUTDOOR','BUSY']::text[]),
